import React,{act,useMemo,useState} from 'react';
import {createRoot} from 'react-dom/client';
import assert from 'node:assert/strict';
import {StagesPage} from '../../src/admin/CompetitionPages';
import ResourcePage from '../../src/admin/ResourcePage';
import {EntityDetailWorkspace,EntityForm} from '../../src/admin/FormComponents';

const Frame=({children,action,title}:any)=><main><h1>{title}</h1>{action}{children}</main>;
const ErrorPanel=({message}:any)=><p role="alert">{message}</p>;
const Detail=(props:any)=><EntityDetailWorkspace {...props} enumLabel={String} formatDate={String}/>;
const Form=(props:any)=><EntityForm {...props} enumLabel={String}/>;
const state=globalThis as any;
function Harness({role='ADMIN'}:{role?:string}){
 const [route,setRoute]=useState('/admin/stages');
 const go=(next:string)=>{history.pushState({},'',next);setRoute(next)};
 const RoutedResource=useMemo(()=>function Routed(props:any){return <ResourcePage {...props} PageFrame={Frame} ErrorPanel={ErrorPanel} LoadingPage={Frame} Empty={Frame} EntityForm={Form} EntityDetailModal={Detail} formatCell={v=>typeof v==='boolean'?String(v):v} getPath={(o,p)=>o[p]}/>},[]);
 return <StagesPage go={go} user={{id:'admin',role} as any} routePath={route} ResourcePage={(props:any)=><RoutedResource {...props} go={go} routePath={route}/>} PageFrame={Frame} ErrorPanel={ErrorPanel} LoadingPage={Frame} PanelTitle={Frame} Empty={Frame} enumLabel={String} formatDate={String}/>;
}
export async function runStageCardActions(){
 const root=createRoot(document.getElementById('root')!);
 const flush=async()=>{await act(async()=>{await new Promise(r=>setTimeout(r,20))})};
 const button=(label:string)=>[...document.querySelectorAll('button')].find(b=>b.textContent===label)!;
 const click=async(el:HTMLElement)=>{assert.ok(el,'expected action exists');await act(async()=>el.click());await flush()};
 await act(async()=>root.render(<Harness/>));await flush();
 const row=()=>document.querySelector('tbody tr') as HTMLElement;
 assert.equal(row().querySelectorAll('button').length,2,'only edit and registration toggle belong in the list');
 assert.equal(button('Удалить навсегда'),undefined);
 await click(button('Закрыть регистрацию'));
 assert.deepEqual(state.__stageCalls.at(-1),{method:'PATCH',path:'/stages/stage-11',body:{registrationOpen:false}});
 assert.ok(button('Открыть регистрацию'));
 state.__stageFail=true;await click(button('Открыть регистрацию'));state.__stageFail=false;
 assert.match(document.querySelector('[role="alert"]')!.textContent!,/Изменение недоступно/);
 assert.ok(button('Открыть регистрацию'));
 await click(row());
 assert.match(location.search,/view=stage-11/);
 assert.ok(button('Афиша'));assert.ok(button('Опубликовать результаты'));
 assert.ok(button('Отменить этап'));assert.ok(button('Удалить навсегда'));
 assert.equal(button('Удалить'),undefined,'cancellation must not masquerade as deletion');
 const before=state.__stageCalls.length;
 await click(button('Опубликовать результаты'));
 assert.equal(state.__stageCalls.length,before,'publication needs confirmation');
 await click(button('Отмена'));
 assert.equal(state.__stageCalls.length,before);
 await click(button('Опубликовать результаты'));
 await click(button('Подтвердить: опубликовать результаты'));
 assert.deepEqual(state.__stageCalls.at(-1),{method:'POST',path:'/stages/stage-11/results-publication',body:{published:true,confirmed:true}});
 assert.ok(button('Скрыть результаты'),'card refreshes after publication');
 await click(button('Отменить этап'));
 assert.equal(state.__stageCalls.at(-1).method,'POST');
 await click(button('Подтвердить отмену этапа'));
 assert.deepEqual(state.__stageCalls.at(-1),{method:'DELETE',path:'/stages/stage-11'});
 assert.equal(button('Отменить этап'),undefined,'cancelled stage cannot be cancelled again');
 await click(button('Удалить навсегда'));
 assert.ok(document.querySelector('[role="dialog"]'));
 assert.equal(document.querySelector('[role="dialog"] .danger-button')?.getAttribute('disabled'),'');
 await click([...document.querySelectorAll('[role="dialog"] button')].find(b=>b.textContent==='Отмена')!);
 await click(button('Редактировать'));
 assert.match(location.pathname,/\/edit$/);
 assert.equal(button('Афиша'),undefined);assert.equal(button('Удалить навсегда'),undefined);
 assert.equal(button('Скрыть результаты'),undefined);
 await click(button('К списку'));
 assert.equal(row().querySelectorAll('button').length,2);
 await click(row());await click(button('Афиша'));
 assert.equal(location.pathname,'/admin/stages/poster');assert.match(location.search,/stageId=stage-11/);
 await act(async()=>root.unmount());
 const readRoot=createRoot(document.getElementById('root')!);
 await act(async()=>readRoot.render(<Harness role="JUDGE"/>));await flush();
 assert.equal(document.querySelector('tbody tr')!.querySelectorAll('button').length,0);
 await click(document.querySelector('tbody tr') as HTMLElement);
 assert.equal(button('Афиша'),undefined);assert.equal(button('Удалить навсегда'),undefined);
 assert.equal(button('Скрыть результаты'),undefined);assert.equal(button('Редактировать'),undefined);
 await act(async()=>readRoot.unmount());
}
